51	export default async function AdminFeedbackPage({
52	  searchParams,
53	}: {
54	  searchParams: Promise<{ kind?: string; status?: string }>;
55	}) {
56	  await requireArea("support");
57	  const sp = await searchParams;
58	
59	  const kind = (KINDS as readonly string[]).includes(sp.kind ?? "") ? sp.kind : undefined;
60	  const status = (STATUSES as readonly string[]).includes(sp.status ?? "") ? sp.status : undefined;
61	
62	  const where: { kind?: string; status?: string } = {};
63	  if (kind) where.kind = kind;
64	  if (status) where.status = status;
65	
66	  const items = await db.feedback.findMany({
67	    where,
68	    include: { user: { select: { email: true, name: true } } },
69	    orderBy: { createdAt: "desc" },
70	  });
71	
72	  const openCount = await db.feedback.count({ where: { status: { in: ["NEW", "PLANNED", "IN_PROGRESS"] } } });
73	
74	  return (
75	    <div className="space-y-6">
76	      <PageHeader
77	        title="Feedback"
78	        sub={`Bug reports and feature requests from customers. ${openCount} open.`}
79	      />
80	
81	      <div className="card space-y-3">
82	        <div className="flex flex-wrap items-center gap-2">
83	          <span className="mr-1 text-xs font-medium text-slate-500">Type</span>
84	          <Pill active={!kind} href={filterHref(undefined, status)}>
85	            All
86	          </Pill>
87	          {KINDS.map((k) => (
88	            <Pill key={k} active={kind === k} href={filterHref(k, status)}>
89	              {k === "BUG" ? "Bugs" : "Features"}
90	            </Pill>
91	          ))}
92	        </div>
93	        <div className="flex flex-wrap items-center gap-2">
94	          <span className="mr-1 text-xs font-medium text-slate-500">Status</span>
95	          <Pill active={!status} href={filterHref(kind, undefined)}>
96	            All
