"use server";

import { revalidatePath } from "next/cache";
import { z } from "zod";
import { db } from "./db";
import { realUser } from "./auth";
import { requireArea } from "./rbac";

/**
 * Staff-side live-chat actions. Every export gates on `requireArea("support")`
 * so only support staff / admins can read or write conversations. This file is
 * a "use server" module, so it may export **async functions only**.
 */

/** Shape returned to the admin inbox client component. */
type InboxMessage = { id: string; sender: string; body: string; createdAt: string };
type InboxConversation = {
  id: string;
  visitorId: string;
  userId: string | null;
  name: string | null;
  email: string | null;
  status: string;
  assignedToId: string | null;
  unreadForAgent: boolean;
  lastMessageAt: string;
  createdAt: string;
  messages: InboxMessage[];
};

/** List conversations for the inbox, unread + newest first. Polled by the client. */
export async function listConversations(): Promise<InboxConversation[]> {
  await requireArea("support");
  const rows = await db.chatConversation.findMany({
    orderBy: [{ unreadForAgent: "desc" }, { lastMessageAt: "desc" }],
    take: 200,
    include: { messages: { orderBy: { createdAt: "asc" } } },
  });
  return rows.map((c) => ({
    id: c.id,
    visitorId: c.visitorId,
    userId: c.userId,
    name: c.name,
    email: c.email,
    status: c.status,
    assignedToId: c.assignedToId,
    unreadForAgent: c.unreadForAgent,
    lastMessageAt: c.lastMessageAt.toISOString(),
    createdAt: c.createdAt.toISOString(),
    messages: c.messages.map((m) => ({
      id: m.id,
      sender: m.sender,
      body: m.body,
      createdAt: m.createdAt.toISOString(),
    })),
  }));
}

/** Fetch a single conversation's messages (used when opening / polling a thread). */
export async function getConversation(id: string): Promise<InboxConversation | null> {
  await requireArea("support");
  if (typeof id !== "string" || !id) return null;
  const c = await db.chatConversation.findUnique({
    where: { id },
    include: { messages: { orderBy: { createdAt: "asc" } } },
  });
  if (!c) return null;
  return {
    id: c.id,
    visitorId: c.visitorId,
    userId: c.userId,
    name: c.name,
    email: c.email,
    status: c.status,
    assignedToId: c.assignedToId,
    unreadForAgent: c.unreadForAgent,
    lastMessageAt: c.lastMessageAt.toISOString(),
    createdAt: c.createdAt.toISOString(),
    messages: c.messages.map((m) => ({
      id: m.id,
      sender: m.sender,
      body: m.body,
      createdAt: m.createdAt.toISOString(),
    })),
  };
}

/**
 * Staff reply: append an "agent" message, flag the thread unread for the user,
 * clear the agent-unread flag, and assign it to the replying staff member.
 */
export async function replyToConversation(
  id: string,
  body: string
): Promise<{ error?: string; ok?: boolean }> {
  const staff = await requireArea("support");

  const parsed = z
    .object({ id: z.string().min(1), body: z.string().trim().min(1).max(5000) })
    .safeParse({ id, body });
  if (!parsed.success) return { error: "Message must be between 1 and 5000 characters." };

  const convo = await db.chatConversation.findUnique({ where: { id: parsed.data.id } });
  if (!convo) return { error: "Conversation not found." };

  await db.$transaction([
    db.chatMessage.create({
      data: { conversationId: parsed.data.id, sender: "agent", body: parsed.data.body },
    }),
    db.chatConversation.update({
      where: { id: parsed.data.id },
      data: {
        status: "OPEN",
        unreadForUser: true,
        unreadForAgent: false,
        assignedToId: staff.id,
        lastMessageAt: new Date(),
      },
    }),
  ]);

  // If the visitor is a signed-in customer, drop them a notification.
  if (convo.userId) {
    await db.notification
      .create({
        data: {
          userId: convo.userId,
          title: "New reply in your live chat",
          href: "/dashboard",
        },
      })
      .catch(() => {});
  }

  revalidatePath("/admin/chat");
  return { ok: true };
}

/** Close a conversation (staff). */
export async function closeConversation(
  id: string
): Promise<{ error?: string; ok?: boolean }> {
  await requireArea("support");
  if (typeof id !== "string" || !id) return { error: "Invalid conversation." };
  const convo = await db.chatConversation.findUnique({ where: { id } });
  if (!convo) return { error: "Conversation not found." };
  await db.chatConversation.update({
    where: { id },
    data: { status: "CLOSED", unreadForAgent: false },
  });
  revalidatePath("/admin/chat");
  return { ok: true };
}

/** Assign a conversation to the acting staff member and mark it read for agents. */
export async function assignConversation(
  id: string
): Promise<{ error?: string; ok?: boolean }> {
  const staff = await requireArea("support");
  if (typeof id !== "string" || !id) return { error: "Invalid conversation." };
  const convo = await db.chatConversation.findUnique({ where: { id } });
  if (!convo) return { error: "Conversation not found." };
  await db.chatConversation.update({
    where: { id },
    data: { assignedToId: staff.id, unreadForAgent: false },
  });
  revalidatePath("/admin/chat");
  return { ok: true };
}

import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";
import { checkRateLimit } from "@/lib/rate-limit";

export const runtime = "nodejs";

/**
 * Public live-chat endpoint used by <ChatWidget/>.
 *
 * POST /api/chat  — start or continue a conversation for a visitorId.
 * GET  /api/chat?visitorId=…  — poll the visitor's open conversation.
 *
 * Everything is scoped strictly by the client-supplied `visitorId`; we never
 * return another visitor's data. Signed-in customers additionally get their
 * `userId` stamped on the conversation. Unauthenticated + write-heavy, so the
 * POST path is rate-limited per IP.
 */

/** First hop of x-forwarded-for is the real client (nginx appends downstream). */
function clientIp(req: Request): string {
  const xff = req.headers.get("x-forwarded-for") ?? "";
  const first = xff.split(",")[0]?.trim();
  return first || "unknown";
}

function clip(v: unknown, max: number): string | null {
  return typeof v === "string" && v.trim() ? v.trim().slice(0, max) : null;
}

function serialize(convo: {
  id: string;
  status: string;
  name: string | null;
  email: string | null;
  messages: { id: string; sender: string; body: string; createdAt: Date }[];
}) {
  return {
    conversation: {
      id: convo.id,
      status: convo.status,
      name: convo.name,
      email: convo.email,
    },
    messages: convo.messages.map((m) => ({
      id: m.id,
      sender: m.sender,
      body: m.body,
      createdAt: m.createdAt.toISOString(),
    })),
  };
}

export async function POST(req: Request) {
  const rl = checkRateLimit(`chat:${clientIp(req)}`, { max: 30, windowMs: 60_000 });
  if (!rl.ok) {
    return NextResponse.json(
      { error: "Too many messages. Please slow down." },
      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
    );
  }

  const raw = (await req.json().catch(() => ({}))) as Record<string, unknown>;
  const visitorId = clip(raw.visitorId, 100);
  const body = clip(raw.body, 5000);
  const name = clip(raw.name, 120);
  const email = clip(raw.email, 200);

  if (!visitorId) return NextResponse.json({ error: "Missing visitorId." }, { status: 400 });
  if (!body) return NextResponse.json({ error: "Message cannot be empty." }, { status: 400 });

  const user = await currentUser();

  // Continue the visitor's existing open conversation, else start a new one.
  let convo = await db.chatConversation.findFirst({
    where: { visitorId, status: "OPEN" },
    orderBy: { lastMessageAt: "desc" },
    select: { id: true, name: true, email: true },
  });

  if (!convo) {
    convo = await db.chatConversation.create({
      data: {
        visitorId,
        userId: user?.id ?? null,
        name: name ?? user?.name ?? null,
        email: email ?? user?.email ?? null,
      },
      select: { id: true, name: true, email: true },
    });
  }

  await db.$transaction([
    db.chatMessage.create({
      data: { conversationId: convo.id, sender: "visitor", body },
    }),
    db.chatConversation.update({
      where: { id: convo.id },
      data: {
        unreadForAgent: true,
        lastMessageAt: new Date(),
        // Backfill identity / link account if it arrives after creation.
        ...(user?.id ? { userId: user.id } : {}),
        ...(name && !convo.name ? { name } : {}),
        ...(email && !convo.email ? { email } : {}),
      },
    }),
  ]);

  const full = await db.chatConversation.findUnique({
    where: { id: convo.id },
    include: { messages: { orderBy: { createdAt: "asc" } } },
  });
  return NextResponse.json(serialize(full!));
}

export async function GET(req: Request) {
  const url = new URL(req.url);
  const visitorId = clip(url.searchParams.get("visitorId"), 100);
  if (!visitorId) return NextResponse.json({ conversation: null, messages: [] });

  const convo = await db.chatConversation.findFirst({
    where: { visitorId, status: "OPEN" },
    orderBy: { lastMessageAt: "desc" },
    include: { messages: { orderBy: { createdAt: "asc" } } },
  });

  if (!convo) return NextResponse.json({ conversation: null, messages: [] });

  // Reading the thread clears the visitor-facing unread flag.
  if (convo.unreadForUser) {
    await db.chatConversation
      .update({ where: { id: convo.id }, data: { unreadForUser: false } })
      .catch(() => {});
  }

  return NextResponse.json(serialize(convo));
}

import { NextResponse } from "next/server";
import { db } from "@/lib/db";

export const runtime = "nodejs";

/**
 * GET /api/chat/[id]?visitorId=…  — fetch a single conversation the widget
 * already knows the id of. Strictly scoped: the row is only returned when its
 * `visitorId` matches the one supplied, so a visitor can never read another's
 * thread by guessing an id. Reading clears the visitor-facing unread flag.
 */

function clip(v: unknown, max: number): string | null {
  return typeof v === "string" && v.trim() ? v.trim().slice(0, max) : null;
}

export async function GET(
  req: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params;
  const url = new URL(req.url);
  const visitorId = clip(url.searchParams.get("visitorId"), 100);

  if (!id || !visitorId) {
    return NextResponse.json({ conversation: null, messages: [] });
  }

  const convo = await db.chatConversation.findFirst({
    where: { id, visitorId },
    include: { messages: { orderBy: { createdAt: "asc" } } },
  });

  if (!convo) return NextResponse.json({ conversation: null, messages: [] });

  if (convo.unreadForUser) {
    await db.chatConversation
      .update({ where: { id: convo.id }, data: { unreadForUser: false } })
      .catch(() => {});
  }

  return NextResponse.json({
    conversation: {
      id: convo.id,
      status: convo.status,
      name: convo.name,
      email: convo.email,
    },
    messages: convo.messages.map((m) => ({
      id: m.id,
      sender: m.sender,
      body: m.body,
      createdAt: m.createdAt.toISOString(),
    })),
  });
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

/**
 * First-party live-chat widget (Tidio-style). Floating bubble bottom-right that
 * opens a chat panel. Identifies the visitor with a persistent `visitorId` in
 * localStorage, posts messages to /api/chat, and polls GET /api/chat every ~4s
 * while open. On the very first message it optionally captures name + email.
 *
 * Mounted by the orchestrator (near <CookieConsent/> in app/layout.tsx) — it
 * does not mount itself anywhere.
 */

type Msg = { id: string; sender: string; body: string; createdAt: string };

const VISITOR_KEY = "nxeon_chat_visitor";
const POLL_MS = 4000;

function getVisitorId(): string {
  try {
    let id = localStorage.getItem(VISITOR_KEY);
    if (!id) {
      id =
        typeof crypto !== "undefined" && crypto.randomUUID
          ? crypto.randomUUID()
          : `v_${Date.now()}_${Math.random().toString(36).slice(2)}`;
      localStorage.setItem(VISITOR_KEY, id);
    }
    return id;
  } catch {
    return `v_${Date.now()}_${Math.random().toString(36).slice(2)}`;
  }
}

export default function ChatWidget() {
  const [open, setOpen] = useState(false);
  const [visitorId, setVisitorId] = useState("");
  const [messages, setMessages] = useState<Msg[]>([]);
  const [draft, setDraft] = useState("");
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [sending, setSending] = useState(false);
  const [error, setError] = useState("");
  const [started, setStarted] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => setVisitorId(getVisitorId()), []);

  const poll = useCallback(async () => {
    if (!visitorId) return;
    try {
      const res = await fetch(`/api/chat?visitorId=${encodeURIComponent(visitorId)}`, {
        cache: "no-store",
      });
      if (!res.ok) return;
      const data = (await res.json()) as { conversation: unknown; messages: Msg[] };
      if (data.conversation) {
        setStarted(true);
        setMessages(data.messages ?? []);
      }
    } catch {
      /* transient network error — next poll retries */
    }
  }, [visitorId]);

  // Poll while the panel is open.
  useEffect(() => {
    if (!open || !visitorId) return;
    poll();
    const t = setInterval(poll, POLL_MS);
    return () => clearInterval(t);
  }, [open, visitorId, poll]);

  // Keep the transcript scrolled to the newest message.
  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight });
  }, [messages, open]);

  async function send() {
    const body = draft.trim();
    if (!body || sending || !visitorId) return;
    setSending(true);
    setError("");
    // Optimistic echo so the input feels instant.
    const optimistic: Msg = {
      id: `tmp_${Date.now()}`,
      sender: "visitor",
      body,
      createdAt: new Date().toISOString(),
    };
    setMessages((m) => [...m, optimistic]);
    setDraft("");
    try {
      const res = await fetch("/api/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          visitorId,
          body,
          name: name.trim() || undefined,
          email: email.trim() || undefined,
        }),
      });
      if (!res.ok) {
        const j = (await res.json().catch(() => ({}))) as { error?: string };
        setError(j.error ?? "Could not send. Please try again.");
        return;
      }
      const data = (await res.json()) as { messages: Msg[] };
      setStarted(true);
      setMessages(data.messages ?? []);
    } catch {
      setError("Network error. Please try again.");
    } finally {
      setSending(false);
    }
  }

  return (
    <div className="fixed bottom-4 right-4 z-[60] flex flex-col items-end gap-3">
      {open && (
        <div className="card glass flex h-[30rem] w-[22rem] max-w-[calc(100vw-2rem)] flex-col overflow-hidden p-0 shadow-2xl">
          {/* Header */}
          <div className="flex items-center justify-between border-b border-white/10 bg-gradient-to-r from-brand-500/20 to-accent-blue/20 px-4 py-3">
            <div>
              <p className="text-sm font-semibold text-slate-100">Chat with us</p>
              <p className="text-[11px] text-slate-400">We typically reply in a few minutes</p>
            </div>
            <button
              aria-label="Close chat"
              onClick={() => setOpen(false)}
              className="rounded-lg p-1 text-slate-400 hover:bg-white/10 hover:text-slate-200"
            >
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <path d="M18 6 6 18M6 6l12 12" />
              </svg>
            </button>
          </div>

          {/* Transcript */}
          <div ref={scrollRef} className="flex-1 space-y-3 overflow-y-auto px-4 py-4">
            {messages.length === 0 && (
              <p className="mt-6 text-center text-sm text-slate-400">
                Hi there! 👋 How can we help you today?
              </p>
            )}
            {messages.map((m) => (
              <div
                key={m.id}
                className={`flex ${m.sender === "visitor" ? "justify-end" : "justify-start"}`}
              >
                <div
                  className={`max-w-[80%] whitespace-pre-wrap rounded-2xl px-3.5 py-2 text-sm ${
                    m.sender === "visitor"
                      ? "bg-brand-500 text-white"
                      : "border border-white/10 bg-white/[0.06] text-slate-200"
                  }`}
                >
                  {m.body}
                </div>
              </div>
            ))}
          </div>

          {/* Composer */}
          <div className="border-t border-white/10 px-3 py-3">
            {!started && (
              <div className="mb-2 flex gap-2">
                <input
                  className="input py-1.5 text-xs"
                  placeholder="Your name (optional)"
                  value={name}
                  maxLength={120}
                  onChange={(e) => setName(e.target.value)}
                />
                <input
                  className="input py-1.5 text-xs"
                  placeholder="Email (optional)"
                  value={email}
                  maxLength={200}
                  onChange={(e) => setEmail(e.target.value)}
                />
              </div>
            )}
            {error && <p className="mb-2 text-xs text-red-400">{error}</p>}
            <div className="flex items-end gap-2">
              <textarea
                className="input min-h-[2.5rem] flex-1 resize-none py-2 text-sm"
                placeholder="Type a message…"
                value={draft}
                maxLength={5000}
                rows={1}
                onChange={(e) => setDraft(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === "Enter" && !e.shiftKey) {
                    e.preventDefault();
                    send();
                  }
                }}
              />
              <button
                className="btn-primary shrink-0 px-3 py-2 text-sm"
                disabled={sending || !draft.trim()}
                onClick={send}
              >
                {sending ? "…" : "Send"}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Floating bubble */}
      <button
        aria-label={open ? "Close chat" : "Open chat"}
        onClick={() => setOpen((o) => !o)}
        className="flex h-14 w-14 items-center justify-center rounded-full bg-gradient-to-br from-brand-500 to-accent-blue text-white shadow-xl transition hover:scale-105"
      >
        {open ? (
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
            <path d="M18 6 6 18M6 6l12 12" />
          </svg>
        ) : (
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
            <path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z" />
          </svg>
        )}
      </button>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState, useTransition } from "react";
import {
  listConversations,
  replyToConversation,
  closeConversation,
  assignConversation,
} from "@/lib/actions-chat";

/**
 * Admin live-chat inbox. Two-pane layout: a conversation list (unread + newest
 * first) and a thread view with a reply box. Polls `listConversations` every
 * few seconds so new visitor messages appear without a manual refresh.
 */

type Msg = { id: string; sender: string; body: string; createdAt: string };
type Convo = {
  id: string;
  visitorId: string;
  userId: string | null;
  name: string | null;
  email: string | null;
  status: string;
  assignedToId: string | null;
  unreadForAgent: boolean;
  lastMessageAt: string;
  createdAt: string;
  messages: Msg[];
};

const POLL_MS = 5000;

function timeAgo(iso: string): string {
  const s = Math.floor((Date.now() - new Date(iso).getTime()) / 1000);
  if (s < 60) return `${s}s ago`;
  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;
  return `${Math.floor(s / 86400)}d ago`;
}

export default function ChatInbox({ initial }: { initial: Convo[] }) {
  const [convos, setConvos] = useState<Convo[]>(initial);
  const [selectedId, setSelectedId] = useState<string | null>(initial[0]?.id ?? null);
  const [draft, setDraft] = useState("");
  const [error, setError] = useState("");
  const [pending, start] = useTransition();
  const scrollRef = useRef<HTMLDivElement>(null);

  const refresh = useCallback(async () => {
    try {
      const rows = await listConversations();
      setConvos(rows);
    } catch {
      /* transient — next poll retries */
    }
  }, []);

  useEffect(() => {
    const t = setInterval(refresh, POLL_MS);
    return () => clearInterval(t);
  }, [refresh]);

  const selected = convos.find((c) => c.id === selectedId) ?? null;

  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight });
  }, [selected?.messages.length, selectedId]);

  function doReply() {
    if (!selected || !draft.trim() || pending) return;
    const body = draft;
    setError("");
    start(async () => {
      const res = await replyToConversation(selected.id, body);
      if (res.error) {
        setError(res.error);
        return;
      }
      setDraft("");
      await refresh();
    });
  }

  function doClose() {
    if (!selected) return;
    start(async () => {
      await closeConversation(selected.id);
      await refresh();
    });
  }

  function doAssign() {
    if (!selected) return;
    start(async () => {
      await assignConversation(selected.id);
      await refresh();
    });
  }

  function label(c: Convo): string {
    return c.name || c.email || `Visitor ${c.visitorId.slice(0, 8)}`;
  }

  return (
    <div className="grid gap-4 lg:grid-cols-[20rem_1fr]">
      {/* Conversation list */}
      <div className="card max-h-[70vh] space-y-1 overflow-y-auto p-2">
        {convos.length === 0 && (
          <p className="p-4 text-center text-sm text-slate-500">No conversations yet.</p>
        )}
        {convos.map((c) => {
          const last = c.messages[c.messages.length - 1];
          const active = c.id === selectedId;
          return (
            <button
              key={c.id}
              onClick={() => setSelectedId(c.id)}
              className={`w-full rounded-xl border px-3 py-2.5 text-left transition ${
                active
                  ? "border-brand-500/50 bg-brand-500/10"
                  : "border-transparent hover:bg-white/[0.04]"
              }`}
            >
              <div className="flex items-center justify-between gap-2">
                <span className="truncate text-sm font-medium text-slate-100">
                  {label(c)}
                </span>
                <div className="flex shrink-0 items-center gap-1.5">
                  {c.unreadForAgent && (
                    <span className="h-2 w-2 rounded-full bg-amber-400" />
                  )}
                  {c.status === "CLOSED" && (
                    <span className="text-[10px] uppercase text-slate-500">closed</span>
                  )}
                </div>
              </div>
              <div className="mt-0.5 flex items-center justify-between gap-2">
                <span className="truncate text-xs text-slate-400">
                  {last ? (last.sender === "agent" ? "You: " : "") + last.body : "…"}
                </span>
                <span className="shrink-0 text-[10px] text-slate-500">
                  {timeAgo(c.lastMessageAt)}
                </span>
              </div>
            </button>
          );
        })}
      </div>

      {/* Thread view */}
      <div className="card flex max-h-[70vh] flex-col p-0">
        {!selected ? (
          <div className="flex flex-1 items-center justify-center p-10 text-sm text-slate-500">
            Select a conversation to view it.
          </div>
        ) : (
          <>
            <div className="flex flex-wrap items-center justify-between gap-2 border-b border-white/10 px-4 py-3">
              <div>
                <p className="text-sm font-semibold text-slate-100">{label(selected)}</p>
                <p className="text-xs text-slate-400">
                  {selected.email || "no email"}
                  {selected.userId ? " · registered customer" : " · guest"} ·{" "}
                  {selected.status.toLowerCase()}
                </p>
              </div>
              <div className="flex items-center gap-2">
                <button
                  className="rounded-lg border border-white/10 px-2.5 py-1 text-xs text-slate-300 hover:bg-white/[0.06] disabled:opacity-50"
                  onClick={doAssign}
                  disabled={pending}
                >
                  Assign to me
                </button>
                {selected.status !== "CLOSED" && (
                  <button
                    className="rounded-lg border border-white/10 px-2.5 py-1 text-xs text-slate-300 hover:bg-white/[0.06] disabled:opacity-50"
                    onClick={doClose}
                    disabled={pending}
                  >
                    Close
                  </button>
                )}
              </div>
            </div>

            <div ref={scrollRef} className="flex-1 space-y-3 overflow-y-auto px-4 py-4">
              {selected.messages.map((m) => (
                <div
                  key={m.id}
                  className={`flex ${m.sender === "agent" ? "justify-end" : "justify-start"}`}
                >
                  <div
                    className={`max-w-[75%] whitespace-pre-wrap rounded-2xl px-3.5 py-2 text-sm ${
                      m.sender === "agent"
                        ? "bg-brand-500 text-white"
                        : "border border-white/10 bg-white/[0.06] text-slate-200"
                    }`}
                  >
                    {m.body}
                    <div
                      className={`mt-1 text-[10px] ${
                        m.sender === "agent" ? "text-white/60" : "text-slate-500"
                      }`}
                    >
                      {timeAgo(m.createdAt)}
                    </div>
                  </div>
                </div>
              ))}
            </div>

            <div className="border-t border-white/10 px-4 py-3">
              {error && <p className="mb-2 text-xs text-red-400">{error}</p>}
              <div className="flex items-end gap-2">
                <textarea
                  className="input min-h-[2.5rem] flex-1 resize-none py-2 text-sm"
                  placeholder="Type your reply…"
                  value={draft}
                  maxLength={5000}
                  rows={1}
                  onChange={(e) => setDraft(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === "Enter" && !e.shiftKey) {
                      e.preventDefault();
                      doReply();
                    }
                  }}
                  disabled={pending}
                />
                <button
                  className="btn-primary shrink-0 px-4 py-2 text-sm"
                  onClick={doReply}
                  disabled={pending || !draft.trim()}
                >
                  {pending ? "…" : "Reply"}
                </button>
              </div>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

import { requireArea } from "@/lib/rbac";
import { db } from "@/lib/db";
import { PageHeader, StatCard } from "@/components/ui/primitives";
import ChatInbox from "@/components/admin/ChatInbox";

export const dynamic = "force-dynamic";

/**
 * Live-chat inbox for support staff. Loads the initial conversation set on the
 * server; the client <ChatInbox/> then polls for new messages and handles
 * replies / assignment / closing via lib/actions-chat.ts.
 */
export default async function AdminChatPage() {
  await requireArea("support");

  const rows = await db.chatConversation.findMany({
    orderBy: [{ unreadForAgent: "desc" }, { lastMessageAt: "desc" }],
    take: 200,
    include: { messages: { orderBy: { createdAt: "asc" } } },
  });

  const openCount = rows.filter((c) => c.status === "OPEN").length;
  const unreadCount = rows.filter((c) => c.unreadForAgent).length;

  const initial = rows.map((c) => ({
    id: c.id,
    visitorId: c.visitorId,
    userId: c.userId,
    name: c.name,
    email: c.email,
    status: c.status,
    assignedToId: c.assignedToId,
    unreadForAgent: c.unreadForAgent,
    lastMessageAt: c.lastMessageAt.toISOString(),
    createdAt: c.createdAt.toISOString(),
    messages: c.messages.map((m) => ({
      id: m.id,
      sender: m.sender,
      body: m.body,
      createdAt: m.createdAt.toISOString(),
    })),
  }));

  return (
    <div className="space-y-6">
      <PageHeader title="Live chat" sub="Real-time conversations from the site widget." />

      <div className="grid grid-cols-2 gap-4 sm:grid-cols-3">
        <StatCard label="Open" value={String(openCount)} />
        <StatCard label="Unread" value={String(unreadCount)} delta={unreadCount > 0 ? "needs a reply" : "all caught up"} deltaGood={unreadCount === 0} />
        <StatCard label="Total" value={String(rows.length)} />
      </div>

      <ChatInbox initial={initial} />
    </div>
  );
}
